        # Check if column c has any pixel != bg
        if any(grid[r][c] != bg for r in range(h)):
            keep_cols.append(c)

    # Construct the output grid
    output = []
    for r in range(h):
        new_row = [grid[r][c] for c in keep_cols]
        output.append(new_row)

